{"implementation":"def solve(case):
    payload = case['payload']
    attempts = payload['attempts']
    max_attempts = payload['max_attempts']
    if not isinstance(attempts, list) or not isinstance(max_attempts, int):
        raise ValueError('Invalid payload structure')
    n = len(attempts)
    if n == 0:
        raise ValueError('No prior attempts, cannot determine reflection')
    last = attempts[-1]
    for key in ['success', 'failure_signature', 'reflection']:
        if key not in last:
            raise ValueError(f'Missing key \'{key}\' in attempt')
    reflection = last['reflection']
    failure_signature = last['failure_signature']
    if last['success']:
        decision = 'stop_success'
        next_index = -1
    else:
        if n >= max_attempts:
            decision = 'stop_budget'
            next_index = -1
        else:
            previous_failures = [a['failure_signature'] for a in attempts[:-1]]
            if last['failure_signature'] in previous_failures:
                decision = 'stop_repeat_failure'
                next_index = -1
            else:
                decision = 'retry'
                next_index = n
    memory_update = {}
    return {
        'decision': decision,
        'next_index': next_index,
        'reflection': reflection,
        'failure_signature': failure_signature,
        'memory_update': memory_update
    }"}
